const App = {
  version: require("./package.json").version,
  platformVersion: require("zapier-platform-core").version,

  // don't forget to register hydrators here!
  // it can be imported from any module
  hydrators: {
    getMovieDetails,
  },

  triggers: {
    new_movie: {
      noun: "Movie",
